/* eslint-disable no-console */
/* globals PIXI */
const City = require('./city');
const MapView = require('./map-view');
require('../sass/default.scss');
const ServerSocketConnector = require('./server-socket-connector');
const ConnectionStateView = require('./connection-state-view');
const showFatalError = require('./lib/show-fatal-error');
const CarOverlay = require('./cars/car-overlay');
const AssetsLoader = require('./assets-loader');
const CarSpawner = require('./cars/car-spawner');
const VariableMapOverlay = require('./variable-map-overlay');
const PowerUpViewMgr = require('./power-up-view-mgr');
const TrafficHandler = require('./power-ups/traffic-handler');
const AutonomousVehicleHandler = require('./power-ups/autonomous-vehicle-handler');
const MaxSpeedHandler = require('./power-ups/max-speed-handler');
const SpawnTramHandler = require('./power-ups/spawn-tram');
const WalkableCityHandler = require('./power-ups/walkable-city-handler');
const DenseCityHandler = require('./power-ups/dense-city-handler');
const AutonomousVehicleLidarHandler = require('./power-ups/autonomous-vehicle-lidar-handler');

const serverHttpUri = process.env.SERVER_HTTP_URI || 'http://localhost:4848';
const serverSocketUri = process.env.SERVER_SOCKET_URI || 'ws://localhost:4848';

fetch(`${serverHttpUri}/config`, { cache: 'no-store' })
  .then(response => {
    if (!response.ok) {
      throw new Error(`HTTP error. Status: ${ response.status }`);
    }
    return response.json();
  })
  .catch((err) => {
    showFatalError(`Error loading configuration from ${serverHttpUri}`, err);
    console.error(`Error loading configuration from ${serverHttpUri}`);
    throw err;
  })
  .then((config) => {
    const city = new City(config.cityWidth, config.cityHeight);

    // Todo: Move to config
    PIXI.settings.SCALE_MODE = PIXI.SCALE_MODES.NEAREST;
    const app = new PIXI.Application({
      width: 1152,
      height: 1152,
      backgroundColor: 0xa6a6a6,
    });
    const assetsLoader = new AssetsLoader();
    assetsLoader.addSpritesheet('roads');
    assetsLoader.addSpritesheet('roads-walkable');
    assetsLoader.addSpritesheet('parks');
    assetsLoader.addSpritesheet('water');
    assetsLoader.addFolder('cars', CarSpawner.allTextureIds(config));
    assetsLoader.load()
      .then((textures) => {
        $('[data-component="app-container"]').append(app.view);

        const mapView = new MapView(city, config, textures);
        app.stage.addChild(mapView.displayObject);
        mapView.displayObject.width = 1152;
        mapView.displayObject.height = 1152;
        mapView.displayObject.x = 0;
        mapView.displayObject.y = 0;

        const carOverlay = new CarOverlay(mapView, config, textures);
        app.ticker.add(time => carOverlay.animate(time));
        const carSpawner = new CarSpawner(carOverlay, config);
        app.ticker.add(time => carSpawner.animate(time));

        const powerUpViewMgr = new PowerUpViewMgr();
        app.ticker.add(time => powerUpViewMgr.animate(time));
        powerUpViewMgr.registerHandler(new TrafficHandler(config, carSpawner));
        powerUpViewMgr.registerHandler(new AutonomousVehicleHandler(config, carSpawner));
        powerUpViewMgr.registerHandler(new MaxSpeedHandler(config, carOverlay));
        powerUpViewMgr.registerHandler(new SpawnTramHandler(config, carSpawner));
        powerUpViewMgr.registerHandler(new WalkableCityHandler(config, mapView));
        powerUpViewMgr.registerHandler(new DenseCityHandler(config, mapView));
        powerUpViewMgr.registerHandler(new AutonomousVehicleLidarHandler(config, carOverlay), true);

        const variableMapOverlay = new VariableMapOverlay(mapView, config);
        app.ticker.add(time => variableMapOverlay.animate(time));

        const connector = new ServerSocketConnector(serverSocketUri);
        connector.events.on('map_update', (cells) => {
          city.map.replace(cells);
        });
        connector.events.on('connect', () => {
          connector.getMap();
          connector.getActivePowerUps();
        });
        connector.events.on('view_show_map_var', (variable, data) => {
          variableMapOverlay.show(data,
            config.variableMapOverlay.colors[variable] || 0x000000);
          setTimeout(() => {
            variableMapOverlay.hide();
          }, config.variableMapOverlay.overlayDuration * 1000);
        });
        connector.events.on('power_ups_update', (activePowerUps) => {
          powerUpViewMgr.update(activePowerUps);
        });

        const connStateView = new ConnectionStateView(connector);
        $('body').append(connStateView.$element);
      })
      .catch((err) => {
        showFatalError('Error loading textures', err);
      });
  })
  .catch((err) => {
    console.error(err);
  });

/* eslint-disable no-console */
/* globals PIXI */
const City = require('./city');
const MapView = require('./map-view');
require('../sass/default.scss');
const ServerSocketConnector = require('./server-socket-connector');
const ConnectionStateView = require('./connection-state-view');
const showFatalError = require('./lib/show-fatal-error');
const CarOverlay = require('./cars/car-overlay');
const AssetsLoader = require('./assets-loader');
const CarSpawner = require('./cars/car-spawner');
const VariableMapOverlay = require('./variable-map-overlay');
const PowerUpViewMgr = require('./power-up-view-mgr');
const TrafficHandler = require('./power-ups/traffic-handler');
const AutonomousVehicleHandler = require('./power-ups/autonomous-vehicle-handler');
const MaxSpeedHandler = require('./power-ups/max-speed-handler');
const SpawnTramHandler = require('./power-ups/spawn-tram');
const WalkableCityHandler = require('./power-ups/walkable-city-handler');
const DenseCityHandler = require('./power-ups/dense-city-handler');
const AutonomousVehicleLidarHandler = require('./power-ups/autonomous-vehicle-lidar-handler');

const serverHttpUri = process.env.SERVER_HTTP_URI || 'http://localhost:4848';
const serverSocketUri = process.env.SERVER_SOCKET_URI || 'ws://localhost:4848';

(async function main() {
  let config;
  try {
    const response = await fetch(`${serverHttpUri}/config`, { cache: 'no-store' });
    if (!response.ok) {
      throw new Error(`HTTP error. Status: ${ response.status }`);
    }
    config = await response.json();
  } catch (err) {
    showFatalError(`Error loading configuration from ${serverHttpUri}`, err);
    console.error(`Error loading configuration from ${serverHttpUri}`);
    console.error(err);
    return;
  }

  const city = new City(config.cityWidth, config.cityHeight);

  // Todo: Move to config
  PIXI.settings.SCALE_MODE = PIXI.SCALE_MODES.NEAREST;
  const app = new PIXI.Application({
    width: 1152,
    height: 1152,
    backgroundColor: 0xa6a6a6,
  });
  const assetsLoader = new AssetsLoader();
  assetsLoader.addSpritesheet('roads');
  assetsLoader.addSpritesheet('roads-walkable');
  assetsLoader.addSpritesheet('parks');
  assetsLoader.addSpritesheet('water');
  assetsLoader.addFolder('cars', CarSpawner.allTextureIds(config));

  let textures;
  try {
    textures = await assetsLoader.load();
  } catch (err) {
    showFatalError('Error loading textures', err);
    return;
  }

  $('[data-component="app-container"]').append(app.view);

  const mapView = new MapView(city, config, textures);
  app.stage.addChild(mapView.displayObject);
  mapView.displayObject.width = 1152;
  mapView.displayObject.height = 1152;
  mapView.displayObject.x = 0;
  mapView.displayObject.y = 0;

  const carOverlay = new CarOverlay(mapView, config, textures);
  app.ticker.add(time => carOverlay.animate(time));
  const carSpawner = new CarSpawner(carOverlay, config);
  app.ticker.add(time => carSpawner.animate(time));

  const powerUpViewMgr = new PowerUpViewMgr();
  app.ticker.add(time => powerUpViewMgr.animate(time));
  powerUpViewMgr.registerHandler(new TrafficHandler(config, carSpawner));
  powerUpViewMgr.registerHandler(new AutonomousVehicleHandler(config, carSpawner));
  powerUpViewMgr.registerHandler(new MaxSpeedHandler(config, carOverlay));
  powerUpViewMgr.registerHandler(new SpawnTramHandler(config, carSpawner));
  powerUpViewMgr.registerHandler(new WalkableCityHandler(config, mapView));
  powerUpViewMgr.registerHandler(new DenseCityHandler(config, mapView));
  powerUpViewMgr.registerHandler(new AutonomousVehicleLidarHandler(config, carOverlay), true);

  const variableMapOverlay = new VariableMapOverlay(mapView, config);
  app.ticker.add(time => variableMapOverlay.animate(time));

  const connector = new ServerSocketConnector(serverSocketUri);
  connector.events.on('map_update', (cells) => {
    city.map.replace(cells);
  });
  connector.events.on('connect', () => {
    connector.getMap();
    connector.getActivePowerUps();
  });
  connector.events.on('view_show_map_var', (variable, data) => {
    variableMapOverlay.show(data,
      config.variableMapOverlay.colors[variable] || 0x000000);
    setTimeout(() => {
      variableMapOverlay.hide();
    }, config.variableMapOverlay.overlayDuration * 1000);
  });
  connector.events.on('power_ups_update', (activePowerUps) => {
    powerUpViewMgr.update(activePowerUps);
  });

  const connStateView = new ConnectionStateView(connector);
  $('body').append(connStateView.$element);
})();

require('../sass/default.scss');
const showFatalError = require('./lib/show-fatal-error');
const IndexListView = require('./index-list-view');
const ServerSocketConnector = require('./server-socket-connector');
const ConnectionStateView = require('./connection-state-view');
const CitizenRequestView = require('./citizen-request-view');
const CitizenRequestViewMgr = require('./citizen-request-view-mgr');
const ActionsPane = require('./dashboard/actions-pane');
const { bindCreateTitle } = require('./dashboard/titles');
const PowerUpSelector = require('./dashboard/power-up-selector');

const serverHttpUri = process.env.SERVER_HTTP_URI || 'http://localhost:4848';
const serverSocketUri = process.env.SERVER_SOCKET_URI || 'ws://localhost:4848';

fetch(`${serverHttpUri}/config`, { cache: 'no-store' })
  .then(response => {
    if (!response.ok) {
      throw new Error(`HTTP error. Status: ${ response.status }`);
    }
    return response.json();
  })
  .catch((err) => {
    showFatalError(`Error loading configuration from ${serverHttpUri}`, err);
    console.error(`Error loading configuration from ${serverHttpUri}`);
    throw err;
  })
  .then((config) => {
    const connector = new ServerSocketConnector(serverSocketUri);
    const languages = config.dashboard.languages;
    const mainLanguage = languages[0];
    const createTitle = bindCreateTitle(languages);

    $('.dashboard')
      .addClass(`with-language-count-${languages.length}`)
      .addClass(`with-main-language-${mainLanguage}`)
      .addClass(languages.map(lang => `with-language-${lang}`).join(' '));

    const citizenRequestView = new CitizenRequestView(config);
    $('#col-1')
      .append(createTitle(config.dashboard.goals.title))
      .append(citizenRequestView.$element);
    const citizenRequestViewMgr = new CitizenRequestViewMgr(citizenRequestView);

    const indexListView = new IndexListView(config);
    $('#col-2')
      .append(createTitle(config.dashboard.status.title))
      .append(indexListView.$element);
    indexListView.setValues({
      'traffic-density': 0,
      'travel-times': 0,
      safety: 0,
      pollution: 0,
      noise: 0,
      'green-spaces': 0,
    });

    $('#col-3')
      .append(createTitle(config.dashboard.powerUps.title))

    const actionsPane = new ActionsPane(config);
    $('#col-actions').append(actionsPane.$element);
    actionsPane.buttons.forEach($button => $button.on('click', (ev) => {
      const actionId = ev.currentTarget.id;
      if ((actionId === 'show-pollution' || actionId === 'show-noise')) {
        actionsPane.disableAll();

        setTimeout(() => {
          actionsPane.enableAll();
        }, (config.variableMapOverlay.overlayDuration
          + config.variableMapOverlay.transitionDuration) * 1000);

        connector.viewShowMapVariable(actionId.replace('show-', ''));
      }
      ev.stopPropagation();
    }));

    const powerUpSelector = new PowerUpSelector(config,
      $('#col-actions-powerup'), $('#col-3'), $('#slide-2'));
    powerUpSelector.events.on('enable', (powerUpId) => {
      connector.enablePowerUp(powerUpId);
    });
    powerUpSelector.events.on('disable', (powerUpId) => {
      connector.disablePowerUp(powerUpId);
    });

    connector.events.on('vars_update', (variables) => {
      indexListView.setValues(variables);
    });
    connector.events.on('goals_update', (goals) => {
      citizenRequestViewMgr.handleUpdate(goals);
    });
    connector.events.on('power_ups_update', (activePowerUps) => {
      powerUpSelector.update(activePowerUps);
    });
    connector.events.on('connect', () => {
      connector.getVars();
      connector.getGoals();
      connector.getActivePowerUps();
      actionsPane.enableAll();
    });

    const connStateView = new ConnectionStateView(connector);
    $('body').append(connStateView.$element);
  })
  .catch((err) => {
    console.error(err);
  });

require('../sass/default.scss');
const showFatalError = require('./lib/show-fatal-error');
const IndexListView = require('./index-list-view');
const ServerSocketConnector = require('./server-socket-connector');
const ConnectionStateView = require('./connection-state-view');
const CitizenRequestView = require('./citizen-request-view');
const CitizenRequestViewMgr = require('./citizen-request-view-mgr');
const ActionsPane = require('./dashboard/actions-pane');
const { bindCreateTitle } = require('./dashboard/titles');
const PowerUpSelector = require('./dashboard/power-up-selector');

const serverHttpUri = process.env.SERVER_HTTP_URI || 'http://localhost:4848';
