  city.map.events.on('update', () => {
    stats.calculateAll();
  });

  // Todo: Move to config
  PIXI.settings.SCALE_MODE = PIXI.SCALE_MODES.NEAREST;
  const app = new PIXI.Application({
    width: 3840,
    height: 1920,
    backgroundColor: 0xf2f2f2,
  });
